// A service wrapping it behind an interface (testable, swappable)
public interface IAiService
{
    Task<string> SummarizeAsync(string text, CancellationToken ct);
}

public class AiService : IAiService
{
    private readonly AzureOpenAIClient _client;
    private readonly ILogger<AiService> _logger;

    public AiService(AzureOpenAIClient client, ILogger<AiService> logger)
    {
        _client = client;
        _logger = logger;
    }

    public async Task<string> SummarizeAsync(string text, CancellationToken ct)
    {
        var chat = _client.GetChatClient("gpt-4o"); // your deployment name
        var response = await chat.CompleteChatAsync(new ChatMessage[]
        {
            new SystemChatMessage("You summarize warehouse incident reports in 3 bullet points."),
            new UserChatMessage(text)
        }, cancellationToken: ct);
        return response.Value.Content[0].Text;
    }
}

