// Expose a C# method as a tool the model can call
public class InventoryPlugin
{
    private readonly IInventoryRepository _repo;
    public InventoryPlugin(IInventoryRepository repo) => _repo = repo;

    [KernelFunction, Description("Gets current stock for a SKU")]
    public async Task<int> GetStockAsync([Description("The product SKU")] string sku)
        => await _repo.GetStockAsync(sku);
}

kernel.Plugins.AddFromObject(new InventoryPlugin(repo));

