public async Task<string> AskAsync(string question, CancellationToken ct)
{
    // 1. Embed the question
    var embedding = await _embeddingClient.GenerateEmbeddingAsync(question, ct);

    // 2. Vector search — Azure AI Search, pgvector, Qdrant, or SQL Server's vector type
    var chunks = await _search.SearchAsync(embedding.Vector, topK: 5, ct);

    // 3. Ground the prompt in the retrieved context
    var context = string.Join("\n---\n", chunks.Select(c => c.Text));
    var prompt = $"""
        Answer using ONLY the context below. If the answer isn't there, say you don't know.
        Context:
        {context}
        Question: {question}
        """;

    // 4. Generate
    var response = await _chatClient.CompleteChatAsync(
        new ChatMessage[] { new UserChatMessage(prompt) }, cancellationToken: ct);
    return response.Value.Content[0].Text;
}

