[ApiController]
[Route("api/[controller]")]
public class AssistantController : ControllerBase
{
    private readonly IAiService _ai;
    private readonly IMemoryCache _cache;

    [HttpPost("ask")]
    [Authorize]
    [EnableRateLimiting("ai-policy")] // LLM calls are expensive
    public async Task<IActionResult> Ask(AskRequest request, CancellationToken ct)
    {
        if (!ModelState.IsValid) return BadRequest(ModelState);

        var cacheKey = $"ai:{request.Question.GetHashCode()}";
        if (_cache.TryGetValue(cacheKey, out string cached))
            return Ok(new { answer = cached });

        try
        {
            var answer = await _ai.AskAsync(request.Question, User.GetUserId(), ct);
            _cache.Set(cacheKey, answer, TimeSpan.FromMinutes(30));
            return Ok(new { answer });
        }
        catch (OperationCanceledException)
        {
            return StatusCode(499); // client gave up
        }
    }
}
